export function CommandPalette({ open, onOpenChange, onCreateClient }: CommandPaletteProps) {
  const router = useRouter()
  const isMobile = useIsMobile()
  const lastKeyRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)

  function navigate(href: string) {
    onOpenChange(false)
    router.push(href)
  }

  // G+X chord handler — mounted globally from AppHeader, but also here for palette-open navigation
  useEffect(() => {
    if (!open) return

    function handleKeyDown(e: KeyboardEvent) {
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return

      const now = Date.now()
      const key = e.key.toLowerCase()

      if (
        lastKeyRef.current === 'g' &&
        now - lastKeyTimeRef.current < G_CHORD_TIMEOUT_MS
      ) {
        const match = NAV_ITEMS.find((n) => n.chord.toLowerCase() === key)
        if (match) {
          e.preventDefault()
          navigate(match.href)
          lastKeyRef.current = ''
          return
        }
      }

      lastKeyRef.current = key
      lastKeyTimeRef.current = now
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [open]) // eslint-disable-line react-hooks/exhaustive-deps

  // B2: mobile → Sheet side="bottom"; desktop → CommandDialog
  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className="h-[85vh] p-0 flex flex-col rounded-t-2xl safe-bottom"
          showCloseButton={false}
        >
          {/* Drag handle */}
          <div className="flex justify-center pt-3 pb-1 shrink-0" aria-hidden="true">
            <div className="h-1 w-10 rounded-full bg-border/60" />
          </div>
          <CommandContent
            isMobile={isMobile}
            onNavigate={navigate}
            onClose={() => onOpenChange(false)}
            onCreateClient={onCreateClient}
          />
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <CommandContent
        isMobile={isMobile}
        onNavigate={navigate}
        onClose={() => onOpenChange(false)}
        onCreateClient={onCreateClient}
      />
    </CommandDialog>
  )
}

